    bitset_t bs;
    assert(bitset_init(&bs, 130)); // 3 64-bit words

    bool bit_val;
    assert(bitset_set(&bs, 0));
    assert(bitset_set(&bs, 63));
    assert(bitset_set(&bs, 64));
    assert(bitset_set(&bs, 129));

