    const char *expected = "Hello, world! Count=42, Hex=0xABCD";
    assert(strcmp(sb.str, expected) == 0);
    assert(sb.len == strlen(expected));
    assert(sb.str[sb.len] == '\0');

    sb_free(&sb);
    printf("C SFT 0006: String builder tests passed.\n");
    return 0;
}

